wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

/// Upper bound on tool-orchestration rounds, so a model that keeps asking for
/// tools can never spin forever inside one `run`.
const MAX_ROUNDS: usize = 8;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` is a precondition the caller
        // guarantees; the bounded `question` is the only free text that
        // crosses into this node.
        let system = "You are a customer support agent. When you need facts \
                      from the knowledge base, call the `lookup` tool with a \
                      focused query; otherwise answer the customer directly \
                      and concisely.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');

        if !ctx.knowledge.is_empty() {
            prompt.push_str("Known context:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    // The only tool in scope is `lookup`, backed by the
                    // read-only knowledge-base handle. Anything else the model
                    // asks for, this node has no authority to invoke.
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!("unsupported tool requested: {}", req.tool),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the round limit".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

